public class Main {
    static long sumValues(java.util.Map<String, Integer> m) {
        long sum = 0;
        for (java.util.Map.Entry<String, Integer> entry : m.entrySet()) sum += entry.getValue();
        return sum;
    }
    public static void main(String[] args) {
        System.out.println(sumValues(java.util.Map.of("a", 2, "b", 3)));
    }
}
